function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
function versions(l){var box=document.getElementById("rc-versions");if(!box)return;var T=window.RC_I18N;var h="";RC_VERSIONS.forEach(function(V,idx){var b="chg."+V.k;var ti=(T[b+".title"]&&T[b+".title"][l])||"";var da=(T[b+".date"]&&T[b+".date"][l])||"";var it="";for(var i=1;i<=9;i++){var e=T[b+".c"+i];if(!e)break;it+="<li>"+esc(e[l]||e.fr)+"</li>";}var cur=idx===0?('<span class="vcur">'+esc((T["versions.current"]&&T["versions.current"][l])||"")+"</span>"):"";h+='<article class="vitem"><div class="vhead"><span class="vnum">'+V.n+"</span>"+cur+'<span class="vdate">'+esc(da)+'</span></div><h3 class="vtitle">'+esc(ti)+'</h3><ul class="vlist">'+it+"</ul></article>";});box.innerHTML=h;}
function apply(l){document.documentElement.lang=l;var T=window.RC_I18N;document.querySelectorAll("[data-i18n]").forEach(function(e){var k=e.getAttribute("data-i18n");if(T[k]&&T[k][l]!=null)e.innerHTML=T[k][l];});versions(l);var s=document.getElementById("rc-lang");if(s)s.value=l;try{localStorage.setItem("rc_lang",l)}catch(_){}}
